extends SceneTree

func _initialize() -> void:
    var arena = load("res://arena.tscn").instantiate()
    var cell = load("res://cell.tscn")
    for y in range(8):
        for x in range(12):
            var item = cell.instantiate()
            item.name = "cell_%d_%d" % [x, y]
            item.position = Vector2(24 + x * 32, 32 + y * 24)
            arena.add_child(item)
            item.owner = arena
    var packed = PackedScene.new()
    var err = packed.pack(arena)
    if err == OK:
        err = ResourceSaver.save(packed, "res://arena.tscn")
    arena.free()
    quit(err)

extends SceneTree

func _initialize() -> void:
    var arena = load("res://arena.tscn").instantiate()
    var layer = TileMapLayer.new()
    layer.name = "Terrain"
    var tiles = TileSet.new()
    var atlas = TileSetAtlasSource.new()
    atlas.texture = ImageTexture.create_from_image(Image.load_from_file("res://terrain.png"))
    tiles.add_physics_layer()
    var source = tiles.add_source(atlas)
    layer.tile_set = tiles
    for i in range(8):
        var cell = Vector2i(i % 4, i >> 2)
        atlas.create_tile(cell)
        if i >= 4:
            var data = atlas.get_tile_data(cell, 0)
            data.add_collision_polygon(0)
            data.set_collision_polygon_points(0, 0, PackedVector2Array([
                Vector2(-8,-8), Vector2(8,-8), Vector2(8,8), Vector2(-8,8)
            ]))
        layer.set_cell(Vector2i(i, 0), source, cell)
    arena.add_child(layer)
    layer.owner = arena
    var packed = PackedScene.new()
    var error = packed.pack(arena)
    if error == OK:
        error = ResourceSaver.save(packed, "res://arena.tscn")
    arena.free()
    quit(error)

extends SceneTree

func _initialize() -> void:
    var frames = SpriteFrames.new()
    frames.add_animation("burst")
    frames.set_animation_speed("burst", 24)
    frames.set_animation_loop("burst", false)
    var sheet = ImageTexture.create_from_image(Image.load_from_file("res://terrain.png"))
    for i in range(2, 8):
        var cell = AtlasTexture.new()
        cell.atlas = sheet
        cell.region = Rect2((i % 4) * 16, (i / 4) * 16, 16, 16)
        frames.add_frame("burst", cell)
    quit(ResourceSaver.save(frames, "res://clips.tres"))
